#!/bin/sh
#
# Generated by the sh backend. Non-POSIX constructs used:
# - 'local': variable scoping (POSIX sh lacks local, but dash/bash/zsh support it)
# - Array emulation (name_0, name_len): arrays are not POSIX
# - '(( ))' arithmetic: required for integer comparison in conditions
# - 'grep -P' helper: PCRE not in POSIX, checked at runtime
#
input_file="$(mktemp)"
max_lines=3
counter=0
printf '# comment\nhas $(sub) here\nplain line\n${param} line\n' >"$input_file"
{
    __ps_tmp0="$(mktemp)"
    grep -v ^# "$input_file" | head -n 3 >$__ps_tmp0
    while { IFS='' true; read -r line && [ -n "$line" ] && [ "$((counter < max_lines))" -ne 0 ]; }; do if printf '%s\n' ""$line"" | grep -Eq '^[[:space:]]*#'; then continue; fi; case "$line" in *\$\(*\)*) printf '%s\n' "Contains command substitution: $line";; *\$\{[^}]*\}*) printf '%s\n' "Contains parameter expansion: $line";; *\$\(\(*\)\)*) printf '%s\n' "Contains arithmetic expansion: $line";; esac; { : $((((counter = counter + 1) - 1))); }; done <$__ps_tmp0
    rm -f $__ps_tmp0
}
rm -f "$input_file"
